  border-color: var(--color-primary);
  box-shadow: var(--shadow-lg);
  position: relative;
}

.pricing-teaser-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-primary);
  color: white;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 16px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.pricing-teaser-card h3 { margin-bottom: 8px; }
.pricing-teaser-price {
  font-family: var(--font-heading);
  font-size: 2.25rem;
  font-weight: 800;
  color: var(--color-navy);
  margin-bottom: 4px;
}
.pricing-teaser-period {
  font-size: 0.875rem;
  color: var(--color-gray-500);
  margin-bottom: 20px;
}
.pricing-teaser-desc {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  margin-bottom: 24px;
}

/* ===== CTA Section ===== */
.cta-section {
  padding: 96px 0;
  background: linear-gradient(135deg, var(--color-navy) 0%, #0D2547 50%, var(--color-primary-dark) 100%);
  color: var(--color-white);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-section::before {
  content: '';
  position: absolute;
  top: -40%;
  left: -10%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(222, 80, 82, 0.15) 0%, transparent 70%);
  border-radius: 50%;
}

.cta-section .container { position: relative; z-index: 1; }
.cta-section h2 { color: var(--color-white); margin-bottom: 16px; }
.cta-section p { color: rgba(255,255,255,0.8); max-width: 560px; margin: 0 auto 36px; font-size: 1.125rem; }

/* ===== Footer ===== */
.footer {
  background: var(--color-navy);
  color: rgba(255, 255, 255, 0.7);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer-brand p { margin-top: 16px; font-size: 0.9375rem; line-height: 1.7; max-width: 280px; }

.footer-col h4 {
  color: var(--color-white);
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 20px;
}

.footer-col a {
  display: block;
  padding: 5px 0;
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.6);
  transition: var(--transition);
}

.footer-col a:hover { color: var(--color-white); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.875rem;
}

.footer-social {
  display: flex;
  gap: 16px;
}

.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
}

.footer-social a:hover { background: rgba(255,255,255,0.15); }

/* ===== Pricing Page ===== */
.billing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 48px;
}

.billing-toggle span { font-weight: 500; color: var(--color-gray-500); transition: var(--transition); }
.billing-toggle span.active { color: var(--color-navy); font-weight: 600; }

.toggle-switch {
  position: relative;
  width: 56px;
  height: 30px;
  cursor: pointer;
}

.toggle-switch input { display: none; }

.toggle-slider {
  position: absolute;
  inset: 0;
  background: var(--color-gray-300);
  border-radius: 15px;
  transition: var(--transition);
}

.toggle-slider::before {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--color-white);
  box-shadow: 0 1px 4px rgba(0,0,0,0.15);
  transition: var(--transition);
}

.toggle-switch input:checked + .toggle-slider {
  background: var(--color-primary);
}

.toggle-switch input:checked + .toggle-slider::before {
  transform: translateX(26px);
}

.save-badge {
  font-size: 0.75rem;
  font-weight: 700;
  background: rgba(222, 80, 82, 0.1);
  color: var(--color-accent);
  padding: 4px 10px;
  border-radius: 20px;
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
  max-width: 1040px;
  margin: 0 auto;
}

.pricing-card {
  background: var(--color-white);
  border-radius: var(--radius);
  padding: 40px 32px;
  box-shadow: var(--shadow);
  border: 2px solid transparent;
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}

.pricing-card.featured {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-xl);
  position: relative;
  transform: scale(1.03);
}

.pricing-card.featured .popular-badge {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-primary);
  color: white;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 6px 20px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.pricing-card-name {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-navy);
  margin-bottom: 8px;
}

.pricing-card-price {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 800;
  color: var(--color-navy);
  line-height: 1;
}

.pricing-card-price .currency { font-size: 1.5rem; vertical-align: top; line-height: 1.5; }
.pricing-card-price .period { font-size: 1rem; font-weight: 500; color: var(--color-gray-500); }

.pricing-card-desc {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  margin: 12px 0 28px;
  min-height: 44px;
}

.pricing-features {
  flex: 1;
  margin-bottom: 28px;
}

.pricing-features li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 8px 0;
  font-size: 0.9375rem;
  color: var(--color-gray-700);
}

.pricing-features li .check {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: rgba(0, 81, 195, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 1px;
}

.pricing-features li .check svg { width: 12px; height: 12px; color: var(--color-primary); }

.pricing-features li.disabled { color: var(--color-gray-300); }
.pricing-features li.disabled .check { background: var(--color-gray-100); }
.pricing-features li.disabled .check svg { color: var(--color-gray-300); }

.pricing-card .btn { width: 100%; }

/* ===== FAQ ===== */
.faq-list {
  max-width: 760px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--color-gray-300);
}

.faq-question {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 0;
  cursor: pointer;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 1.0625rem;
  color: var(--color-navy);
  background: none;
  border: none;
  width: 100%;
  text-align: left;
  transition: var(--transition);
}

.faq-question:hover { color: var(--color-primary); }

.faq-icon {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--color-gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
}

.faq-item.active .faq-icon {
  background: var(--color-primary);
  color: white;
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}

.faq-answer-inner {
  padding: 0 0 24px;
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--color-gray-700);
}

.faq-item.active .faq-answer {
  max-height: 200px;
}

/* ===== Feature Detail Sections ===== */
.feature-detail {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.feature-detail.reverse { direction: rtl; }
.feature-detail.reverse > * { direction: ltr; }

.feature-detail-content {}
.feature-detail-content .section-label { text-align: left; }
.feature-detail-content h2 { text-align: left; margin-bottom: 16px; }
.feature-detail-content p { margin-bottom: 24px; }

.feature-detail-visual {
  background: var(--color-gray-100);
  border-radius: var(--radius);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.feature-detail-visual .visual-placeholder {
  color: var(--color-primary);
  opacity: 0.15;
}

.feature-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.feature-list li {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.9375rem;
  color: var(--color-gray-700);
}

.feature-list li svg { flex-shrink: 0; color: var(--color-primary); }

/* ===== Integrations ===== */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 28px;
}

.integration-card {
  background: var(--color-white);
  border-radius: var(--radius);
  padding: 32px 24px;
  box-shadow: var(--shadow);
  border: 1px solid rgba(0,0,0,0.04);
  text-align: center;
  transition: var(--transition);
}

.integration-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-lg); }

.integration-icon {
  width: 56px;
  height: 56px;
  background: var(--color-gray-100);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  color: var(--color-primary);
}

.integration-card h3 { font-size: 1.125rem; margin-bottom: 10px; }
.integration-card p { font-size: 0.875rem; }
.integration-brands {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
  margin-top: 12px;
}
.integration-brands span {
  font-size: 0.8125rem;
  padding: 4px 10px;
  background: var(--color-gray-100);
  border-radius: 20px;
  color: var(--color-gray-700);
}

/* ===== About Page ===== */
.mission-section {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.mission-visual {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-navy) 100%);
  border-radius: var(--radius);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
}

.team-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}

.team-card { text-align: center; }

.team-avatar {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--color-gray-100), var(--color-gray-300));
  margin: 0 auto 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.75rem;
  color: var(--color-primary);
}

.team-card h3 { margin-bottom: 4px; font-size: 1.125rem; }
.team-card p { font-size: 0.9375rem; color: var(--color-gray-500); }

/* ===== Contact Page ===== */
.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
}

.contact-form { }

.form-group {
  margin-bottom: 20px;
}

.form-group label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-navy);
  margin-bottom: 6px;
}

.form-group label .required { color: var(--color-accent); }

.form-control {
  width: 100%;
  padding: 12px 16px;
  font-family: var(--font-body);
  font-size: 1rem;
  border: 2px solid var(--color-gray-300);
  border-radius: var(--radius-sm);
  background: var(--color-white);
  transition: var(--transition);
  color: var(--color-gray-900);
}

.form-control:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(0, 81, 195, 0.1);
}

.form-control.error {
  border-color: var(--color-accent);
}

.form-error {
  font-size: 0.8125rem;
  color: var(--color-accent);
  margin-top: 4px;
  display: none;
}

.form-group.has-error .form-error { display: block; }

textarea.form-control { resize: vertical; min-height: 120px; }

.form-success {
  display: none;
  background: #ECFDF5;
  border: 1px solid #6EE7B7;
  border-radius: var(--radius-sm);
  padding: 20px;
  text-align: center;
  color: #065F46;
  font-weight: 500;
}

.form-success.show { display: block; }

.contact-info { }

.contact-info-item {
  display: flex;
  gap: 16px;
  margin-bottom: 32px;
}

.contact-info-icon {
  width: 48px;
  height: 48px;
  background: rgba(0, 81, 195, 0.08);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--color-primary);
}

.contact-info-item h4 { margin-bottom: 4px; }
.contact-info-item p { font-size: 0.9375rem; }

.offices { margin-top: 48px; }
.offices h3 { margin-bottom: 24px; }

.office-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.office-card {
  background: var(--color-gray-100);
  border-radius: var(--radius-sm);
  padding: 20px;
}

.office-card h4 { font-size: 0.9375rem; margin-bottom: 4px; }
.office-card p { font-size: 0.875rem; }
.office-card .badge {
  display: inline-block;
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 8px;
  background: rgba(0, 81, 195, 0.08);
  color: var(--color-primary);
  border-radius: 4px;
  margin-top: 8px;
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .features-grid { grid-template-columns: 1fr 1fr; }
  .steps-grid { grid-template-columns: 1fr 1fr; }
  .pricing-teaser-cards { grid-template-columns: 1fr; max-width: 400px; }
  .pricing-cards { grid-template-columns: 1fr; max-width: 420px; }
  .pricing-card.featured { transform: none; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .integrations-grid { grid-template-columns: 1fr 1fr; }
  .team-grid { grid-template-columns: 1fr 1fr; }
  .feature-detail { grid-template-columns: 1fr; gap: 40px; }
  .feature-detail.reverse { direction: ltr; }
  .mission-section { grid-template-columns: 1fr; gap: 40px; }
  .contact-grid { grid-template-columns: 1fr; gap: 48px; }
  .office-cards { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-cta { display: none; }
  .hamburger { display: flex; }
  .mobile-nav { display: block; }

  .hero { padding: 120px 0 60px; }
  .hero-page { padding: 110px 0 48px; }
  .section { padding: 64px 0; }
  .stats-banner { padding: 56px 0; }
  .stats-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .steps-grid { grid-template-columns: 1fr; max-width: 400px; margin: 0 auto; }
  .features-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }
  .cta-section { padding: 64px 0; }
  .hero-buttons { flex-direction: column; }
  .hero-buttons .btn { width: 100%; }
}

@media (max-width: 480px) {
  .stats-grid { grid-template-columns: 1fr; }
  .testimonial-card { padding: 32px 20px; }
  .pricing-card { padding: 32px 24px; }
}
